tool_input.command:
cd resources/js/pages/posts && for f in New Edit; do
python3 - "$f" <<'EOF'
import sys
f=sys.argv[1]+'.tsx'
s=open(f).read()
s=s.replace("import { Head, useForm } from '@inertiajs/react'
","import { Head, useForm } from '@inertiajs/react'
import { useTranslation } from '@guren/inertia-client'
")
if f=='New.tsx':
    s=s.replace("export default function NewPost() {
","export default function NewPost() {
  const { t } = useTranslation()
")
    s=s.replace('<Head title="New post" />',"<Head title={t('posts.new_title')} />").replace("          New post
","          {t('posts.new_title')}
").replace("            Publish
","            {t('posts.publish')}
")
else:
    s=s.replace("export default function EditPost({ post }: Props) {
","export default function EditPost({ post }: Props) {
  const { t } = useTranslation()
")
    s=s.replace("<Head title={`Edit ${post.title}`} />","<Head title={t('posts.edit_head', { title: post.title })} />").replace("          Edit post
","          {t('posts.edit_title')}
").replace("            Save changes
","            {t('posts.save')}
")
for a,b in (('Title','title'),('Excerpt','excerpt'),('Body','body')):
    s=s.replace('>%s</label>'%a,">{t('posts.%s')}</label>"%b)
open(f,'w').write(s)
EOF
done; cd ../../../..; bunx guren codegen 2>&1 | tail -3; bun run typecheck 2>&1 | tail -15; bunx guren check --i18n 2>&1 | tail -8
